import pandas as pd

df = pd.read_excel('macpac_medicaid_enrollment_by_eligibility_group_fy2023.xlsx', sheet_name='Exhibit 14', header=None)
disabled_col = None
for c in df.columns:
    if 'Disabled' in str(df.iloc[4, c]):
        disabled_col = c
        break
pa_row = None
for r in range(len(df)):
    if str(df.iloc[r, 0]).strip().startswith('Pennsylvania'):
        pa_row = r
        break
result = float(df.iloc[pa_row, disabled_col])

import pandas as pd

df = pd.read_excel('macpac_medicaid_enrollment_by_eligibility_group_fy2023.xlsx', sheet_name='Exhibit 14', header=None)
tx_child, ca_child = None, None
for r in range(6, 57):
    name = str(df.iloc[r, 0]).strip()
    if name.startswith('Texas'):
        tx_child = float(df.iloc[r, 2])
    elif name.startswith('California'):
        ca_child = float(df.iloc[r, 2])
result = 'yes' if tx_child > ca_child else 'no'

import pandas as pd

df = pd.read_excel('macpac_medicaid_enrollment_by_eligibility_group_fy2023.xlsx', sheet_name='Exhibit 14', header=None)
target_states = ['California', 'New York', 'Pennsylvania']
total = 0.0
for r in range(6, 57):
    state_cell = str(df.iloc[r, 0]).strip()
    for s in target_states:
        if state_cell.startswith(s):
            total += float(df.iloc[r, 3])
result = round(total, 3)
